#include<bits/stdc++.h>

using namespace std;
typedef long long ll;
const ll NMAX=1e5+5,MOD=1e9+7;
ll v[NMAX],pos[NMAX];
void tc(){
    ll n,l,r,ans=1;
    cin>>n;
    for(ll i=0;i<n;i++){
        cin>>v[i];
        pos[v[i]]=i;
    }
    l=r=pos[0];
    for(ll i=1;i<n;i++){
        if(pos[i]<l) l=pos[i];
        else if(pos[i]>r) r=pos[i];
        else ans=ans*(r-l+1-i)%MOD;
    }
    cout<<ans<<'\n';
}
int main()
{
    ios_base::sync_with_stdio(false); cin.tie(0);
    ll t;
    cin>>t;
    while(t--)
        tc();
    return 0;
}

#include<bits/stdc++.h>

using namespace std;
typedef long long ll;
const ll NMAX=5e3+5;
ll dp[NMAX],v[NMAX],fr[NMAX];
void testcase(){
    ll n,ans=0;
    cin>>n;
    for(ll i=1;i<=n;i++){
        cin>>v[i];
        dp[i]=0;
    }
    for(ll i=0;i<=n;i++){

        if(i && dp[i]==0) continue;
        ll frmax=0;
        for(int j=1;j<=n;j++) fr[j]=0;

        for(int j=i+1;j<=n;j++){
            if((j-i)%2 && frmax<=(j-i)/2 && (i==0 || v[i]==v[j]))
                dp[j]=max(dp[j],dp[i]+1);
            frmax=max(frmax,++fr[v[j]]);
        }
    }

    ll frmax=0;
    for(int j=1;j<=n;j++) fr[j]=0;

    for(int i=n;i>=0;i--){
        if((n-i)%2==0 && frmax<=(n-i)/2) ans=max(ans,dp[i]);
        frmax=max(frmax,++fr[v[i]]);
    }
    cout<<ans<<'\n';
}
int main()
{
    ios_base::sync_with_stdio(false); cin.tie(0);
    int t;
    cin>>t;
    while(t--)
        testcase();
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;

const int nmax = 5e6 + 5;
int appear[nmax];
int mxval[nmax];
int toggle[nmax];

int main()
{
    cin.tie(nullptr)->sync_with_stdio(false);
    int t;
    cin >> t;
    while (t--)
    {
        int n, m, mn = nmax, mx = 0;
        cin >> n >> m;
        for (int i = 0; i <= m; ++i)
        {
            appear[i] = toggle[i] = mxval[i] = 0;
        }
        for (int i = 0, x; i < n; i++)
        {
            cin >> x;
            appear[x] = 1;
            toggle[x] = 1;
            mn = min(mn, x);
            mx = max(mx, x);
        }
        for (int i = 0; i <= mx; i++)
        {
            mxval[i] = i;
        }
        int ptr = mx, smax = mx - mn;
        for (int i = mx; i >= 1; i--)
        {
            for (ll j = (ll)i * i; j <= mx; j += i)
            {
                if (appear[j])
                    toggle[mxval[j]]--;
                mxval[j] = min(mxval[j], mxval[j / i]);
                if (appear[j])
                    toggle[mxval[j]]++;
            }
            while (toggle[ptr] == 0)
                ptr--;
            if (i <= mn)
                smax = min(smax, ptr - i);
        }
        cout << smax << '\n';
    }
}
